import re
import string


class LongestWord:

    def __init__(self):
        self.word_list = []

    def add_word(self, word):
        self.word_list.append(word)

    def find_longest_word(self, sentence):
        cleaned_sentence = self._clean_sentence(sentence)
        words = self._split_into_words(cleaned_sentence)
        return self._find_longest_matched_word(words)

    def _clean_sentence(self, sentence):
        sentence = sentence.lower()
        sentence = re.sub('[%s]' % re.escape(string.punctuation), '', sentence)
        return sentence

    def _split_into_words(self, cleaned_sentence):
        return re.split(' ', cleaned_sentence)

    def _find_longest_matched_word(self, words):
        longest_word = ""
        for word in words:
            if word in self.word_list and len(word) > len(longest_word):
                longest_word = word
        return longest_word
